<h1 class="h3 mb-4">Notifiche</h1><div class="list-group shadow-sm"><?php if(!$records): ?><div class="list-group-item text-secondary">Nessuna notifica.</div><?php endif ?><?php foreach($records as $n): ?><div class="list-group-item <?= $n['letta_il']?'':'list-group-item-primary' ?>"><div class="d-flex justify-content-between"><strong><?= e($n['titolo']) ?></strong><small><?= e($n['creato_il']) ?></small></div><p class="mb-2"><?= e($n['messaggio']) ?></p><?php if($n['link']): ?><a href="<?= e($n['link']) ?>">Apri</a><?php endif ?><?php if(!$n['letta_il']): ?><form class="d-inline ms-2" method="post" action="/app/notifiche/<?= (int)$n['id'] ?>/letta"><?= $csrf->field() ?><button class="btn btn-sm btn-outline-secondary">Segna letta</button></form><?php endif ?></div><?php endforeach ?></div>
